#include "ark/agent.hpp"
#include "ark/drawings.hpp"
#include "ark/iteration_history.hpp"
#include "native_process.hpp"
#include <cmath>
#include <iostream>
#include <limits>
#include <stdexcept>

using namespace ark;using V=arkjson::Value;
namespace {
void check(bool ok,const std::string& message){if(!ok)throw std::runtime_error(message);}
V& member(V& value,const char* key){for(auto& entry:value.obj)if(entry.first==key)return entry.second;throw std::runtime_error("Missing mutable test field");}
V json(const std::string& text){V out;check(arkjson::parse(text,out),"Test JSON must parse");return out;}
V data(const V& response){check(!response.find("isError")->b,response.find("structuredContent")->dump());return *response.find("structuredContent");}
V applyArgs(const AgentSession& s,const V& commands){V out=V::makeObj();out.set("expected_revision",V::makeNum((double)s.revision));out.set("commands",commands);return out;}
V apply(AgentSession& s,const std::string& commands){return data(s.call("doc_apply",applyArgs(s,json(commands))));}
V fixture(){return json(R"({"name":"Bracket drawing","feature":1,"units":"mm","scale":1,"paper_mm":[297,210],"views":[{"name":"Top","type":"orthographic","direction":"top","offset_mm":[45,70]},{"name":"Front","type":"orthographic","direction":"front","offset_mm":[45,125]},{"name":"Section A-A","type":"section","direction":"top","origin_mm":[0,0,5],"offset_mm":[175,70]}],"dimensions":[{"name":"Width","view":"Top","kind":"horizontal","reference_a":"x_min","reference_b":"x_max","position_mm":[55,85],"tolerance":{"lower":-0.1,"upper":0.2,"units":"mm"}},{"name":"Height","view":"Front","kind":"vertical","reference_a":"z_min","reference_b":"z_max","position_mm":[98,123]}]})");}
V setCommand(const V& drawing){V out=V::makeObj(),commands=V::makeArr();out.set("op",V::makeStr("drawing.set"));out.set("drawing",drawing);commands.arr.push_back(out);return commands;}
V inspect(AgentSession& s){return data(s.call("drawing_inspect",json(R"({"name":"Bracket drawing"})")));}
void core(){
    V drawing=fixture();validateDrawing(drawing,false);V binding=json(R"({"brep_base64_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","topology_sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","observed_revision":9})");drawing.set("binding",binding);validateDrawing(drawing,true);
    Document original;Feature f;f.type=FeatureType::Box;f.name="Persisted definition";original.addFeature(f);original.drawings.push_back(drawing);const auto text=documentToJson(original);check(json(text).find("version")->num==36,"Authored drawing selects document v36");check(text.find("display_polyline")==std::string::npos&&text.find("measured_mm")==std::string::npos,"Derived projections and measurements are not persisted");Document loaded;std::string error;check(documentFromJson(text,loaded,&error),error);check(loaded.drawings[0].dump()==json(text).find("drawings")->arr[0].dump(),"Drawing authoring and source binding roundtrip");check(loaded.authoringCopy().drawings[0].dump()==loaded.drawings[0].dump(),"Authoring copy retains drawing source");
    auto root=json(text);root.set("version",V::makeNum(35));const auto stable=documentToJson(loaded);check(!documentFromJson(root.dump(),loaded,&error)&&documentToJson(loaded)==stable,"Older format cannot admit drawing data and load rejection is atomic");
    root=json(text);member(root,"drawings").arr[0].set("unsupported",V::makeBool(true));check(!documentFromJson(root.dump(),loaded,&error),"Unknown drawing fields reject");
    root=json(text);member(member(member(root,"drawings").arr[0],"dimensions").arr[0],"tolerance").set("units",V::makeStr("in"));check(!documentFromJson(root.dump(),loaded,&error),"Mismatched tolerance units reject");
    Document empty;check(json(documentToJson(empty)).find("version")->num==1,"Application identity does not upgrade documents without drawing data");
    AgentSession s;s.suppressFailureCapture();const auto revision=s.revision;V args=V::makeObj();args.set("commands",setCommand(fixture()));check(s.call("doc_apply",args).find("isError")->b&&s.revision==revision,"Drawing writes require an observed revision");check(!s.call("agent_onboard",json(R"({"topic":"drawings"})")).find("isError")->b,"Drawing onboarding is discoverable");
    bool inspectFound=false,exportFound=false,drawingSchema=false;for(const auto& tool:AgentSession::tools().arr){inspectFound|=tool.find("name")->str=="drawing_inspect";exportFound|=tool.find("name")->str=="drawing_export";if(tool.find("name")->str=="doc_apply"){const auto& properties=*tool.find("inputSchema")->find("properties")->find("commands")->find("items")->find("properties");bool set=false,refresh=false,remove=false;for(const auto& op:properties.find("op")->find("enum")->arr){set|=op.str=="drawing.set";refresh|=op.str=="drawing.refresh";remove|=op.str=="drawing.remove";}drawingSchema=set&&refresh&&remove&&properties.find("drawing")&&properties.find("drawing")->find("properties")->find("views");}}check(inspectFound&&exportFound&&drawingSchema,"Drawing tools, commands and authored view schema are discoverable");
}
#ifdef ARK_DRAWING_NATIVE_TESTS
void native(const char* previewPath){
    native_test::TempDirectory workspace("ark-drawing-test-");AgentSession s;s.suppressFailureCapture();
    apply(s,R"([{"op":"feature.add","type":"native_solid","name":"Bracket","native":{"op":"box"},"p":{"width":40,"depth":20,"height":10}}])");
    data(s.call("doc_apply",applyArgs(s,setCommand(fixture()))));auto report=inspect(s);check(report.find("status")->str=="current"&&report.find("views")->arr.size()==3,"Orthographic and section views resolve at the source revision");check(report.find("views")->arr[0].find("method")->str=="OCCT_HLRBRep_Algo"&&report.find("views")->arr[2].find("method")->str=="OCCT_exact_plane_section","Exact HLR and exact section owners are used");check(std::abs(report.find("dimensions")->arr[0].find("value")->num-40)<1e-8&&std::abs(report.find("dimensions")->arr[1].find("value")->num-10)<1e-8,"Dimensions measure actual source references");
    const auto digest=report.find("current_brep_base64_sha256")->str;check(digest==iterationSha256(s.document.evalBodies[0].nativeData.find("brep_base64")->str),"Source binding hashes the exact observed B-rep");for(const auto& view:report.find("views")->arr)for(const auto& edge:view.find("edges")->arr)check(!edge.find("exact_brep_base64")->str.empty()&&edge.find("display_polyline_mm")->arr.size()>=2,"Projected exact curves are retained independently of display samples");
    for(size_t index=0;index<3;++index){double xmin=1e9,xmax=-1e9,ymin=1e9,ymax=-1e9;for(const auto& edge:report.find("views")->arr[index].find("edges")->arr)for(const auto& point:edge.find("display_polyline_mm")->arr){xmin=std::min(xmin,point.arr[0].num);xmax=std::max(xmax,point.arr[0].num);ymin=std::min(ymin,point.arr[1].num);ymax=std::max(ymax,point.arr[1].num);}check(std::abs(xmin)<1e-8&&std::abs(xmax-40)<1e-8&&std::abs(ymin)<1e-8&&std::abs(ymax-(index==1?10:20))<1e-8,"Actual exact projected curves follow the authored top/front/section frames and source extents");}
    const auto topology=*s.document.evalBodies[0].nativeData.find("topology");s.document.evalBodies[0].nativeData.set("topology",V::makeObj());check(inspect(s).find("status")->str=="stale","Semantic topology changes invalidate binding even with unchanged B-rep bytes");s.document.evalBodies[0].nativeData.set("topology",topology);
    auto preserved=s.document.evalBodies[0].baked?std::make_unique<Mesh>(*s.document.evalBodies[0].baked):nullptr;s.document.evalBodies[0].baked=std::make_unique<Mesh>();auto meshIndependent=inspect(s);check(meshIndependent.find("current_brep_base64_sha256")->str==digest&&meshIndependent.find("dimensions")->dump()==report.find("dimensions")->dump(),"Empty display mesh cannot choose drawing geometry or measurements");s.document.evalBodies[0].baked=std::move(preserved);
    const auto current=s.revision;V output=json(R"({"name":"Bracket drawing","format":"svg"})");output.set("expected_revision",V::makeNum((double)current));output.set("path",V::makeStr(native_test::pathUtf8(workspace.path()/"drawing.svg")));auto receipt=data(s.call("drawing_export",output));auto svg=native_test::readFile(workspace.path()/"drawing.svg");check(svg.find("40 mm")!=std::string::npos&&svg.find("-0.1, +0.2")!=std::string::npos&&s.revision==current,"SVG contains measured dimensions and declared tolerance without changing revision");check(s.call("drawing_export",output).find("isError")->b&&native_test::readFile(workspace.path()/"drawing.svg")==svg,"Existing drawing exports are never replaced");
    if(previewPath)std::filesystem::copy_file(workspace.path()/"drawing.svg",std::filesystem::u8path(previewPath));
    output.set("format",V::makeStr("json"));output.set("path",V::makeStr(native_test::pathUtf8(workspace.path()/"drawing.json")));data(s.call("drawing_export",output));check(json(native_test::readFile(workspace.path()/"drawing.json")).find("views")->arr[0].find("edges")->arr[0].find("exact_brep_base64"),"JSON export retains derived exact curve custody");
    const auto document=native_test::pathUtf8(workspace.path()/"drawing.ark");check(saveDocument(s.document,document.c_str()),"Drawing SQLite save succeeds");Document loaded;std::string error;check(loadDocument(document.c_str(),loaded,&error),error);loaded.recompute();V query=json(R"({"name":"Bracket drawing"})");check(inspectDrawing(loaded,query,100).find("status")->str=="current","Save/reopen uses geometry binding rather than a fabricated session revision match");check(loaded.iterationHistory.t==V::Obj,"Drawing edits retain immutable document history");
    apply(s,R"([{"op":"feature.edit","id":1,"p":{"width":55}}])");report=inspect(s);check(report.find("status")->str=="stale"&&!report.find("dimensions")&&!report.find("views"),"Source edit invalidates old projections and dimensions");output.set("expected_revision",V::makeNum((double)s.revision));output.set("path",V::makeStr(native_test::pathUtf8(workspace.path()/"stale.svg")));check(s.call("drawing_export",output).find("isError")->b&&!std::filesystem::exists(workspace.path()/"stale.svg"),"Stale drawing cannot be exported");
    V stale=applyArgs(s,json(R"([{"op":"drawing.refresh","name":"Bracket drawing"}])"));stale.set("expected_revision",V::makeNum((double)s.revision-1));const auto before=documentToJson(s.document);check(s.call("doc_apply",stale).find("isError")->b&&documentToJson(s.document)==before,"Stale expected_revision cannot refresh a drawing");
    apply(s,R"([{"op":"drawing.refresh","name":"Bracket drawing"}])");report=inspect(s);check(std::abs(report.find("dimensions")->arr[0].find("value")->num-55)<1e-8&&report.find("current_brep_base64_sha256")->str!=digest,"Explicit refresh derives new geometry and measurements");
    apply(s,R"([{"op":"feature.edit","id":1,"native":{"op":"cylinder"},"p":{"radius":5,"height":12}}])");const auto baseline=documentToJson(s.document);const auto rev=s.revision;check(s.call("doc_apply",applyArgs(s,json(R"([{"op":"drawing.refresh","name":"Bracket drawing"}])"))).find("isError")->b&&s.revision==rev&&documentToJson(s.document)==baseline,"Removed semantic references reject refresh atomically");
    data(s.call("doc_undo",json("{\"expected_revision\":"+std::to_string(s.revision)+"}")));check(inspect(s).find("status")->str=="current","Undo restores the exact bound solid and drawing association");
    V missing=fixture();member(missing,"views").arr[2].set("origin_mm",json("[0,0,1000]"));const auto untouched=documentToJson(s.document);check(s.call("doc_apply",applyArgs(s,setCommand(missing))).find("isError")->b&&documentToJson(s.document)==untouched,"Section missing its source rejects the full authored drawing transaction");
    apply(s,R"([{"op":"feature.remove","id":1}])");report=inspect(s);check(report.find("status")->str=="invalid"&&s.document.drawings.size()==1,"Deleting source preserves authored drawing and reports invalid association");check(documentFromJson(documentToJson(s.document),loaded,&error)&&loaded.drawings.size()==1,"Invalid association persists for explicit user repair");
    AgentSession cylinder;cylinder.suppressFailureCapture();apply(cylinder,R"([{"op":"feature.add","type":"native_solid","name":"Pin","native":{"op":"cylinder"},"p":{"radius":12.7,"height":25.4}}])");V pin=fixture();pin.set("units",V::makeStr("in"));pin.set("views",json(R"([{"name":"Top","type":"orthographic","direction":"top","offset_mm":[75,75]}])"));pin.set("dimensions",json(R"([{"name":"Diameter","view":"Top","kind":"diameter","reference_a":"axis","position_mm":[100,45],"tolerance":{"lower":-0.001,"upper":0.002,"units":"in"}}])"));data(cylinder.call("doc_apply",applyArgs(cylinder,setCommand(pin))));auto inches=inspect(cylinder);check(std::abs(inches.find("dimensions")->arr[0].find("value")->num-1)<1e-8,"Exact circular diameter converts declared units to inches");
    member(pin,"views").arr[0].set("direction",V::makeStr("front"));check(cylinder.call("doc_apply",applyArgs(cylinder,setCommand(pin))).find("isError")->b,"Radial dimension in an oblique view rejects");
    AgentSession dependent;dependent.suppressFailureCapture();apply(dependent,R"([{"op":"feature.add","type":"native_solid","name":"Explicit source","native":{"op":"box"},"p":{"width":40,"depth":20,"height":10}},{"op":"feature.add","type":"native_solid","name":"Dependent placement","inputs":[1],"native":{"op":"transform"},"p":{"tx":200}}])");data(dependent.call("doc_apply",applyArgs(dependent,setCommand(fixture()))));check(inspect(dependent).find("dimensions")->arr[0].find("value")->num==40&&dependent.document.drawings[0].find("feature")->num==1,"Drawing uses explicit source ID even when another feature consumes it");
    AgentSession mesh;mesh.suppressFailureCapture();apply(mesh,R"([{"op":"feature.add","type":"mesh_body","name":"Triangle mesh","mesh":{"positions":[0,0,0,10,0,0,0,10,0],"indices":[0,1,2]}}])");const auto meshRevision=mesh.revision;const auto meshBefore=documentToJson(mesh.document);check(mesh.call("doc_apply",applyArgs(mesh,setCommand(fixture()))).find("isError")->b&&mesh.revision==meshRevision&&documentToJson(mesh.document)==meshBefore,"Mesh source rejects atomically without manufacturing a drawing solid");
    AgentSession mixed;mixed.suppressFailureCapture();apply(mixed,R"([{"op":"feature.add","type":"native_solid","name":"Drawing source","native":{"op":"box"},"p":{"width":40,"depth":20,"height":10}},{"op":"feature.add","type":"native_solid","name":"Separate face extrusion","inputs":[1],"native":{"op":"extrude","source_face":"z_max"},"p":{"depth":"12","direction":"-1","symmetric":"1"}}])");data(mixed.call("doc_apply",applyArgs(mixed,setCommand(fixture()))));
    const auto mixedBytes=documentToJson(mixed.document);check(json(mixedBytes).find("version")->num==36,"Drawings and extended extrusion share one version 36 source contract");Document mixedReloaded;check(documentFromJson(mixedBytes,mixedReloaded,&error),error);mixedReloaded.recompute();
    const auto mixedDrawing=inspectDrawing(mixedReloaded,json(R"({"name":"Bracket drawing"})"),100);check(mixedDrawing.find("status")->str=="current"&&std::abs(mixedDrawing.find("dimensions")->arr[0].find("value")->num-40)<1e-8&&mixedReloaded.find(2)->get("direction")=="-1","Version 36 reopen retains current drawing association and extended extrusion source");
}
#endif
}
int main(int argc,char** argv){try{core();
#ifdef ARK_DRAWING_NATIVE_TESTS
native(argc==3&&std::string(argv[1])=="--preview"?argv[2]:nullptr);
#endif
std::cout<<"associative drawing tests passed\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
